  failedStat: { kind: stat, source: "failed", caption: "リトライ待ち", unit: " 件", label: "失敗" }

lanes:
  origin: { x: 0, width: 200 }
  infra: { x: 220, width: 280 }
  devices: { x: 520, width: 240 }

states:
  queued: 0
